// Monta a mensagem de alerta a partir do payload padrão do Error Trigger do n8n.
const erro = $input.first().json;

const nomeWorkflow = erro.workflow && erro.workflow.name ? erro.workflow.name : '(desconhecido)';
const execucaoId = erro.execution && erro.execution.id ? erro.execution.id : '(desconhecido)';
const execucaoUrl = erro.execution && erro.execution.url ? erro.execution.url : '';
const nodeComErro = erro.trigger && erro.trigger.error && erro.trigger.error.node && erro.trigger.error.node.name
  ? erro.trigger.error.node.name
  : (erro.execution && erro.execution.lastNodeExecuted) || '(desconhecido)';
const mensagemErro = erro.trigger && erro.trigger.error && erro.trigger.error.message
  ? erro.trigger.error.message
  : JSON.stringify(erro).slice(0, 500);

const texto = [
  '⚠️ *Falha na automação de Notas Fiscais*',
  '',
  `Workflow: ${nomeWorkflow}`,
  `Node com erro: ${nodeComErro}`,
  `Execução: ${execucaoId}`,
  execucaoUrl ? `Link: ${execucaoUrl}` : null,
  '',
  `Mensagem: ${mensagemErro}`,
].filter(Boolean).join('\n');

return [{ json: { texto } }];
